if($section==='email'){
 if(admin()['role']!=='admin')abort(403,'Owner access required');
 admin_page('Email Delivery',function(){?><p class="muted">Automatic email uses encrypted SMTP credentials and a CLI cron worker. Saving credentials does not send email. Set up the worker in cPanel and test with a real mailbox.</p>
 <form class="form" method="post" action="/admin/email/settings"><?=token()?>
 <label>SMTP hostname<input name="smtp_host" value="<?=esc(setting('smtp_host'))?>" required placeholder="mail.yourdomain.com"></label>
