 <label>SMTP username<input name="smtp_user" value="<?=esc(setting('smtp_user'))?>"></label>
 <label>SMTP password (leave blank to keep current)<input type="password" autocomplete="new-password" name="smtp_password"></label>
 <label>From email<input name="smtp_from" type="email" value="<?=esc(setting('smtp_from'))?>" required></label>
