 <button class="btn gold">Save SMTP Settings</button></form>
 <h3>Delivery Queue</h3><p class="muted">A sent status means the SMTP server accepted the message, not guaranteed inbox delivery.</p><div class="scroll"><table><tr><th>Recipient</th><th>Subject</th><th>Status</th><th>Attempts</th><th>Action</th></tr><?php foreach(all('SELECT id,recipient,subject,status,attempts,last_error FROM email_queue ORDER BY id DESC LIMIT 100') as $e):?><tr><td><?=esc($e['recipient'])?></td><td><?=esc($e['subject'])?></td><td><?=esc($e['status'])?><?php if($e['last_error']):?><small><?=esc($e['last_error'])?></small><?php endif;?></td><td><?=(int)$e['attempts']?></td><td><?php if($e['status']==='failed'):?><form method="post" action="/admin/email/retry"><?=token()?><input type="hidden" name="id" value="<?=$e['id']?>"><button class="btn">Retry</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php });exit;
}
